def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    if op_c == 0:
        return 'D'
    last_my = my[-1]
    last_op = op[-1]
    if last_op == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                run += 1
            else:
                break
        if run >= 2:
            return 'D'
        if op_d * 3 > n:
            return 'D'
        if last_my == 'D':
            return 'C'
        return 'D'
    if op_c * 5 >= n * 4:
        return 'C'
    if op_d * 2 > n:
        return 'D'
    return 'C'
